// HELPERS
// ─────────────────────────────────────────────────────────────────────────────

export function getLevelInfo(totalXP) {
  const level = Math.min(100, Math.floor(totalXP / 82) + 1);
  const entry = LEVEL_TITLES.find(t => level >= t.range[0] && level <= t.range[1]) || LEVEL_TITLES[0];
  return { level, title: entry.title, icon: entry.icon, color: entry.color,
           xpForLevel:(level-1)*82, xpToNext:level*82 };
}

export function getTotalLessons() {
  return COURSE_ORDER.reduce((s,id) => s + COURSES[id].lessons.length, 0);
}
